"""The operator's procedure for one prepared SMB qualification, with its paths filled in."""

from __future__ import annotations

from pathlib import Path
from typing import Any


def write_operator_steps(root: Path, record: dict[str, Any]) -> Path:
    """Write ``OPERATOR_STEPS.md`` into the campaign folder; return its path."""
    sources = record["sources"]
    campaign = record["campaign_id"]
    lines = [
        f"# SMB qualification - campaign `{campaign}`",
        "",
        "Generated by `python -m omr_scanner.tools.smb_qualification prepare`. The general",
        "procedure and what the result means are in `docs/release/SMB_QUALIFICATION.md`.",
        "",
        "## Machines",
        "",
        "* **OMRFlow machine** - this one. It runs the supervisor and OMRFlow. The project",
        "  database is created on *this machine's local disk* (the run refuses a network drive).",
    ]
    for source in sources:
        lines.append(
            f"* **Scanner PC {source['label']}** - shares the folder OMRFlow watches as "
            f"`{source['root']}` and a log folder readable here as "
            f"`{Path(source['writer_log']).parent}`."
        )
    lines += [
        "",
        "## Before the run",
        "",
        "1. On every scanner PC: create the scanner folder and the log folder (siblings - the",
        "   log folder must NOT be inside the scanner folder), share them, and give the account",
        "   OMRFlow runs as read access (read/write on the log folder for the clock probe).",
        "2. From this machine, check each share lists: `Get-ChildItem <root>`.",
        "3. Synchronise the clocks (`w32tm /resync` on every machine) and record",
        "   `w32tm /stripchart /computer:<scanner-pc> /samples:5 /dataonly` from this machine.",
        "4. Copy each `packages/writer_<label>` folder to its scanner PC (any local folder).",
        "",
        "## The run",
        "",
        "```powershell",
        f"python -m omr_scanner.tools.smb_qualification run --campaign \"{root}\"",
        "# add --coordinator-exe \"$env:LOCALAPPDATA\\Programs\\OMRFlow\\OMRFlow.exe\" to run",
        "# OMRFlow itself from the installed build",
        "```",
        "",
        "When it prints **START THE WRITERS NOW**, run on each scanner PC the command in its",
        "package's `RUN-ON-SCANNER-PC.txt`:",
        "",
    ]
    for source in sources:
        target = source.get("writer_target") or r"D:\Scans\omr"
        log = (source.get("writer_log_local")
               or rf"D:\Scans\omrflow-smb-logs\writer_{source['label']}.jsonl")
        lines += [
            f"* Scanner PC {source['label']}:",
            "  ```powershell",
            "  powershell -NoProfile -ExecutionPolicy Bypass `",
            "      -File .\\Invoke-OmrflowScannerWriter.ps1 `",
            f"      -Package . -Target \"{target}\" -Log \"{log}\"",
            "  ```",
        ]
    lines += [
        "",
        "The supervisor then, on its own:",
        "",
        "* waits until both writers have logged `writer_started`;",
        "* **kills OMRFlow** (`TerminateProcess`) once about 35 % of the files are written,",
        "  with a sheet in a recognition worker, and restarts it after more files were written",
        "  while it was down;",
        "* at about 60 % prints **CHECKPOINT: TAKE SHARE ... AWAY NOW** - make that share",
        "  unreachable from this machine *without stopping its writer* (disable the scanner PC's",
        "  network adapter, unplug its cable, or `Stop-Service LanmanServer -Force` on it). The",
        "  supervisor waits until it observes the share gone - here and in the project's source",
        "  status - keeps it away at least two minutes, then prints **BRING SHARE ... BACK NOW**",
        "  and waits until it observes it back;",
        "* waits for every writer to finish and every file to be read, stops OMRFlow cleanly,",
        "  and writes `smb/report.json` and `smb/report.md`.",
        "",
        "## After the run",
        "",
        "Copy each scanner PC's writer log back into the campaign folder only if the run could",
        "not read it (it reads them over the network). Commit the compact report under",
        "`docs/release/validation/` as `SMB_QUALIFICATION.md` describes. Never commit images.",
        "",
    ]
    path = root / "OPERATOR_STEPS.md"
    path.write_text("\n".join(lines), encoding="utf-8")
    return path


__all__ = ["write_operator_steps"]
